using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionToEnemyWithMostCorruptionOmenLogic", menuName = "Data/Battle/Omens System/Omen Logic/BattleActionToEnemyWithMostCorruptionOmenLogic Omen Logic")]
public class BattleActionToEnemyWithMostCorruptionOmenLogic : OmenLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private bool directPurify;

	public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		if (currentCorruptedAnimals.activeCorruptedAnimals.Count == 0)
		{
			return;
		}
		GameObject enemyWithMostCorruption = currentCorruptedAnimals.GetEnemyWithMostCorruption();
		if (!(enemyWithMostCorruption == null))
		{
			if (directPurify)
			{
				enemyWithMostCorruption.GetComponent<CorruptionStats>().Purify(actionValue, source, corruptionPurifyModifierEnum, playSFX);
			}
			else
			{
				battleAction.CastTargetAmount(enemyWithMostCorruption, actionValue, source);
			}
		}
	}
}
